$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1') -Force -WarningAction SilentlyContinue;$module=Get-Module Repato.MayaQaWorkflow
$id=[pscustomobject]@{RequestId='request-1';TaskId='task-1';WorkflowId='workflow-1';QaWorkflowId='create-plan-views-v1';AttemptId='attempt-1';RunId='run-1';ClaimId='claim-1'}
$positive={param($launch)[pscustomobject]@{RequestId=$id.RequestId;TaskId=$id.TaskId;WorkflowId=$id.WorkflowId;QaWorkflowId=$id.QaWorkflowId;AttemptId=$id.AttemptId;RunId=$id.RunId;ClaimId=$id.ClaimId;EvidenceAccepted=$true;RollbackProven=$true;Verified=$true}}
$launch=[pscustomobject]@{NativeProcessId=4242;RequestId='request-1'};$ok=Wait-MayaQaCanonicalResultPhase -Launch $launch -Identity $id -ResultProvider $positive
if($ok.RequestId -ne $id.RequestId){throw 'Positive resume correlation failed.'}
$negativeNames='TaskId','WorkflowId','QaWorkflowId','RunId','AttemptId','ClaimId','RequestId';$passed=0
foreach($name in $negativeNames){$field=$name;$provider={param($l)$x=& $positive $l;$x.$field='wrong';$x}.GetNewClosure();$rejected=$false;try{Wait-MayaQaCanonicalResultPhase -Launch $launch -Identity $id -ResultProvider $provider|Out-Null}catch{$rejected=$true};if(!$rejected){throw "Resume mismatch was accepted: $name"};$passed++}
$evidenceNames='EvidenceAccepted','RollbackProven','Verified';$evidencePassed=0
foreach($name in $evidenceNames){$field=$name;$provider={param($l)$x=& $positive $l;$x.$field=$false;$x}.GetNewClosure();$rejected=$false;try{$x=Wait-MayaQaCanonicalResultPhase -Launch $launch -Identity $id -ResultProvider $provider;Complete-MayaQaCanonicalExecutionPhase -Result $x|Out-Null}catch{$rejected=$true};if(!$rejected){throw "Invalid resume evidence was accepted: $name"};$evidencePassed++}
$expiryPassed=0;foreach($value in 'not-a-date',((Get-Date).ToUniversalTime().AddMinutes(-1).ToString('O'))){$provider={param($l)$x=& $positive $l;$x|Add-Member NoteProperty ExpiresUtc $value -Force;$x}.GetNewClosure();$rejected=$false;try{Wait-MayaQaCanonicalResultPhase -Launch $launch -Identity $id -ResultProvider $provider|Out-Null}catch{$rejected=$true};if(!$rejected){throw "Invalid resume expiry was accepted: $value"};$expiryPassed++}
$root=Join-Path ([IO.Path]::GetTempPath()) ('maya-result-timeout-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $root|Out-Null
try {
    $nativeId=[guid]::NewGuid().ToString('N');$requestPath=Join-Path $root 'synthetic.request.json';$resultPath=$requestPath+'.result.json'
    $identity=[pscustomobject]@{RequestId=$requestPath;NativeRequestId=$nativeId;TaskId='synthetic-task';WorkflowId='synthetic-workflow';QaWorkflowId='create-plan-views-v1';TestId='create-plan-views-v1';HandoffId='synthetic-handoff';AttemptId='synthetic-attempt';RunId='synthetic-run';ClaimId='synthetic-claim'}
    [ordered]@{schemaVersion=2;requestId=$nativeId;TaskId=$identity.TaskId;WorkflowId=$identity.WorkflowId;QaWorkflowId=$identity.QaWorkflowId;TestId=$identity.TestId;HandoffId=$identity.HandoffId;AttemptId=$identity.AttemptId;RunId=$identity.RunId;ClaimId=$identity.ClaimId;expiresUtc=[DateTimeOffset]::UtcNow.AddMinutes(5).ToString('O')}|ConvertTo-Json -Compress|Set-Content -LiteralPath $requestPath -Encoding UTF8
    $started=[DateTimeOffset]::UtcNow;$timedOut=$false;$timeoutError=$null;try{& $module {param($path,$id) Get-MayaQaCanonicalNativeResult -RequestPath $path -Identity $id -TimeoutSeconds 1 -SecurityPromptProvider {$null}} $requestPath $identity|Out-Null}catch{$timeoutError=$_.Exception.Message;$timedOut=$timeoutError -match 'result wait timed out'}
    $elapsed=([DateTimeOffset]::UtcNow-$started).TotalSeconds
    if(!$timedOut -or $elapsed -lt 0.75 -or $elapsed -gt 5 -or !(Test-Path -LiteralPath $requestPath -PathType Leaf) -or (Test-Path -LiteralPath $resultPath -PathType Leaf)){throw "A result timeout was not bounded and non-destructive: timedOut=$timedOut elapsed=$elapsed error=$timeoutError requestExists=$(Test-Path -LiteralPath $requestPath -PathType Leaf) resultExists=$(Test-Path -LiteralPath $resultPath -PathType Leaf)"}
    [pscustomobject]@{ResumePositiveCase='PASS';ResumeCorrelationNegativeCasesPassed=$passed;ResumeCorrelationNegativeCasesTotal=$negativeNames.Count;ResumeEvidenceNegativeCasesPassed=$evidencePassed;ResumeEvidenceNegativeCasesTotal=$evidenceNames.Count;ResumeExpiryNegativeCasesPassed=$expiryPassed;ResumeExpiryNegativeCasesTotal=2;ResultTimeout='Bounded, state-preserving';ElapsedSeconds=[Math]::Round($elapsed,2);ResumeTerminalStateVerified=$true;RealStoreMutated=$false;RealNativeRequestSent=$false;RevitLaunched=$false}|ConvertTo-Json -Compress
} finally {if([IO.Path]::GetFullPath($root).StartsWith([IO.Path]::GetFullPath([IO.Path]::GetTempPath()),[StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $root)){Remove-Item -LiteralPath $root -Recurse -Force}}
